/// 应用多语言字符串
enum AppLocale { zh, en }

class AppStrings {
  final AppLocale locale;
  final AppShell shell;
  final BluetoothStrings bluetooth;
  final ScanStrings scan;
  final DeviceStrings device;
  final BatteryStrings battery;
  final CommandStrings command;
  final ParamStrings param;
  final RecordStrings record;
  final CommonStrings common;

  const AppStrings._({
    required this.locale,
    required this.shell,
    required this.bluetooth,
    required this.scan,
    required this.device,
    required this.battery,
    required this.command,
    required this.param,
    required this.record,
    required this.common,
  });

  static const zh = AppStrings._(locale: AppLocale.zh, shell: AppShell.zh, bluetooth: BluetoothStrings.zh, scan: ScanStrings.zh, device: DeviceStrings.zh, battery: BatteryStrings.zh, command: CommandStrings.zh, param: ParamStrings.zh, record: RecordStrings.zh, common: CommonStrings.zh);
  static const en = AppStrings._(locale: AppLocale.en, shell: AppShell.en, bluetooth: BluetoothStrings.en, scan: ScanStrings.en, device: DeviceStrings.en, battery: BatteryStrings.en, command: CommandStrings.en, param: ParamStrings.en, record: RecordStrings.en, common: CommonStrings.en);

  String protocolField(String? zh, String? en) => locale == AppLocale.zh ? (zh ?? en ?? '') : (en ?? zh ?? '');
}

